import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const n = Number(lines[0]);
const d = lines.slice(1, n + 1).map((l) => l.split(" ").map(Number));

// dp[mask * n + v] = 訪問済みの集合が mask で、今 v にいるときの最小コスト
const full = 1 << n;
const dp = new Float64Array(full * n).fill(Infinity);
dp[1 * n + 0] = 0; // 都市 1（添字 0）から出発
for (let mask = 1; mask < full; mask++) {
  if (!(mask & 1)) continue; // 出発地を含まない状態は使わない
  for (let v = 0; v < n; v++) {
    const cur = dp[mask * n + v];
    if (cur === Infinity) continue;
    for (let to = 0; to < n; to++) {
      if (mask & (1 << to)) continue;
      const next = (mask | (1 << to)) * n + to;
      if (cur + d[v][to] < dp[next]) dp[next] = cur + d[v][to];
    }
  }
}

let best = Infinity;
for (let v = 0; v < n; v++) best = Math.min(best, dp[(full - 1) * n + v] + d[v][0]);
console.log(best);
